import{_ as t,o,c as a,a2 as r}from"./chunks/framework.BDCokyix.js";const u=JSON.parse('{"title":"UI Revamp v0 — Assistant + Bot References (Deeper Pass)","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/prd/ui-revamp-v0-refs-assistant-bots.md","filePath":"architecture/prd/ui-revamp-v0-refs-assistant-bots.md","lastUpdated":1780254295000}'),s={name:"architecture/prd/ui-revamp-v0-refs-assistant-bots.md"};function n(i,e,d,c,l,h){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="ui-revamp-v0-—-assistant-bot-references-deeper-pass" tabindex="-1">UI Revamp v0 — Assistant + Bot References (Deeper Pass) <a class="header-anchor" href="#ui-revamp-v0-—-assistant-bot-references-deeper-pass" aria-label="Permalink to &quot;UI Revamp v0 — Assistant + Bot References (Deeper Pass)&quot;">​</a></h1><p>Companion to <a href="./ui-revamp-v0">ui-revamp-v0.md</a>. Follow-up to the first refs pass (<a href="./ui-revamp-v0-refs">ui-revamp-v0-refs.md</a>), which already covered the four-column layout, the bot-add 2-step inline form, the composer-footer backend switcher chip, and the inline mention pill.</p><p>This pass goes deeper on the <em>assistant</em> and <em>bot</em> surfaces:</p><ul><li>§4.3 — Adding an ACP backend in space settings (transport URL + auth, default flag).</li><li>§4.6 — Visually distinguishing a bot <em>command dispatch</em> from a chat message.</li><li>§4.4 — Bot status indicators (<code>pending</code> / <code>active</code> / <code>failed</code>) and inline error surfaces.</li><li>Streaming responses — tokens streaming in, stop / cancel / regenerate controls.</li></ul><p>Keep the same rules as the prior pass: every recommendation is grounded in a real product screen; sections lock to <code>### Borrow</code> and <code>### Avoid</code>; the table at the bottom maps PRD refs to chosen patterns.</p><h2 id="_1-adding-an-acp-backend-prd-§4-3" tabindex="-1">1. Adding an ACP backend (PRD §4.3) <a class="header-anchor" href="#_1-adding-an-acp-backend-prd-§4-3" aria-label="Permalink to &quot;1. Adding an ACP backend (PRD §4.3)&quot;">​</a></h2><p>Settings → Assistant tab. The user lists configured backends, adds new ones by entering a transport URL + auth, validates inline, and marks one as default for the space. AI-provider config screens and developer-credential screens are the strongest signal here.</p><h3 id="borrow" tabindex="-1">Borrow <a class="header-anchor" href="#borrow" aria-label="Permalink to &quot;Borrow&quot;">​</a></h3><ul><li><strong>Linear — Create API key</strong> (<a href="https://refero.design/pages/13f7be48-a227-412a-aa85-5544121d14ba" target="_blank" rel="noreferrer">screen 13f7be48</a>). Single-column form, dark mode, three blocks: <code>Key name</code> (single text input), <code>Permissions</code> with a &quot;Full access&quot; radio + &quot;Only select permissions…&quot; radio that expands into 5 named checkboxes (<code>Read</code>, <code>Write</code>, <code>Create issues</code>, <code>Create comments</code>, <code>Admin</code>), and a <code>Team access</code> block with a second radio + chip selector for teams. Footer is <code>Cancel</code> / <code>Create</code>. This is the exact shape we want for &quot;Add an ACP backend&quot;: one screen, no wizard, the optional complexity (permissions / scopes) reveals only when the user asks for it. Apply it field-for-field to our backend form: <code>Name</code> · <code>Transport URL</code> · <code>Auth</code> (radio: none / bearer token / custom header) · <code>Mark as default for space</code> (single checkbox). Footer Cancel / Save. Nothing else.</li><li><strong>Cursor — Dashboard → Integrations</strong> (<a href="https://refero.design/pages/069970f5-0a6f-4ebf-964a-3cbf1744de7d" target="_blank" rel="noreferrer">screen 069970f5</a>). Reference for the <em>list state</em> once one or more backends are configured. Each row is a single horizontal stripe: provider mark (left), provider name + one-line subtext (<code>Connect &lt;provider&gt; for Cloud Agents, Bugbot and enhanced codebase context</code> / <code>Connected as &#39;referodesignteam&#39; to repositories in GitHub organizations: referodesignteam</code>), and a right-aligned action button (<code>Manage ⌄</code> when connected, <code>Connect ↗</code> when not). The visual treatment alone tells the user the connected-vs-unconnected state — no colored badges shouting &quot;ACTIVE&quot; in green. We adopt this for our backend list: connected backends show <code>Manage ⌄</code> (with a sub-menu including &quot;Mark as default&quot;, &quot;Edit&quot;, &quot;Remove&quot;); unconfigured backends ship as templates (Ollama / LM Studio / Codex / OpenAI-compatible) with a <code>Configure</code> button until populated.</li><li><strong>Fingerprint — Cloudflare integration detail</strong> (<a href="https://refero.design/pages/d60dbde8-7ae3-4101-96dc-a33b4979675a" target="_blank" rel="noreferrer">screen d60dbde8</a>). Useful for the <em>single-backend detail</em> surface: provider header, a single <code>Status: Not Installed</code> (or <code>Connected</code>) pill directly under the title, then a long body of marketing/help text and a single primary CTA. We don&#39;t need the marketing prose, but the structure <em>title + status pill on its own line, then config below</em> is the right anchor for our backend detail view.</li><li><strong>Default-flag pattern.</strong> None of the reviewed screens express &quot;default&quot; with a separate control — they all use either a radio (one item only) or an inline pill next to the selected item&#39;s name. Settle on <strong>a pill <code>Default</code> shown to the right of the backend name</strong> in the list, set/unset from the row&#39;s <code>Manage ⌄</code> menu. A radio group across rows is wrong because the user may have <em>zero</em> defaults (per-message override only).</li></ul><h3 id="avoid" tabindex="-1">Avoid <a class="header-anchor" href="#avoid" aria-label="Permalink to &quot;Avoid&quot;">​</a></h3><ul><li><strong>Manus connectors modal</strong> (<a href="https://refero.design/pages/fae7ea60-633b-41f9-ae4d-1472b72f062c" target="_blank" rel="noreferrer">screen fae7ea60</a>). Centered modal with a 3×N grid of provider cards. This is a <em>picker for a catalog</em> and reads as &quot;first choose, then configure&quot; — two surfaces for one task. Our list is short (4–6 templates) and lives directly in the settings tab; no modal, no grid.</li><li>Token entry fields rendered as plain <code>&lt;input type=text&gt;</code>. Even though ACP tokens for local Ollama are not real secrets, the affordance matters: always <code>type=password</code> with a reveal toggle on the right edge. Borrow this from any standard secret-input pattern; do not invent one.</li><li>&quot;Test connection&quot; buttons that fire only on click. Validate the transport URL <strong>on blur</strong> (same rule the first refs pass locked for the peer-address paste in §4.4): parse, attempt an ACP <code>initialize</code> handshake, render the result <em>inline under the field</em> — green check + &quot;Connected as &lt;agent name / version&gt;&quot;, or red message with the error. No toast, no modal.</li></ul><h2 id="_2-bot-command-dispatch-in-chat-prd-§4-6" tabindex="-1">2. Bot command dispatch in chat (PRD §4.6) <a class="header-anchor" href="#_2-bot-command-dispatch-in-chat-prd-§4-6" aria-label="Permalink to &quot;2. Bot command dispatch in chat (PRD §4.6)&quot;">​</a></h2><p>When the user writes <code>@bot:foo do X</code> in chat, the message must read as a <em>command</em> sent to a runtime, not as a chat utterance. The response comes back as a bot-attributed message in the same panel. The closest references in Refero are terminal-style command+response pairings inside chat threads, and agent-detail screens that interleave commands with their outputs.</p><h3 id="borrow-1" tabindex="-1">Borrow <a class="header-anchor" href="#borrow-1" aria-label="Permalink to &quot;Borrow&quot;">​</a></h3><ul><li><strong>Cursor — Agent detail</strong> (<a href="https://refero.design/pages/5f4c68ff-da25-49e1-b7ba-6bcbf76a5ee6" target="_blank" rel="noreferrer">screen 5f4c68ff</a>). This is the strongest reference we found for <em>command dispatch in a chat-shaped thread</em>. The conversation thread interleaves model-attributed messages (<code>GPT-5.2 High</code>, <code>Opus 4.6</code> chips at the top of each block), code-diff blocks rendered as monospace gutters with syntax-highlighted lines, and <strong>a terminal-style block</strong> showing <code>$ cd /workspace &amp;&amp; git add AGENTS.md &amp;&amp; git commit -m &quot;Add AGENTS.md ...&quot;</code> followed by its output (<code>[cursor/agents-markdown-file-f408 db90c72] Add AGENTS.md with project conventions and guidelines / 1 file changed, 84 insertions(+) / create mode 100644 AGENTS.md</code>) in the same monospace face. Lock this exactly for our bot dispatch: <ul><li>The user&#39;s message containing <code>@bot:foo do X</code> renders with the body in the normal text face, <strong>but the part after the mention pill is wrapped in a monospace span</strong> with a leading <code>$ </code> prefix (or similar disambiguator), styled at the same density as a code block. Visually: chat sentence on top, terminal-shaped command body beneath it.</li><li>The bot&#39;s response message renders with a <code>bot:foo</code> attribution pill in the header (distinct from user/LLM avatars — same icon set as the §4.5 mention pill), and the body uses a monospace face when the bot returns structured output (ack, status, list) and the proportional face when the bot returns prose.</li></ul></li><li><strong>Raycast AI — &quot;Thinking…&quot; expandable block</strong> (<a href="https://refero.design/pages/d3118a5e-b48a-4a6b-b7d9-d0668641d05b" target="_blank" rel="noreferrer">screen d3118a5e</a>). When a model is working, Raycast renders a small dark pill labelled <code>Thinking… &gt;</code> with the chevron indicating it can expand into reasoning detail. We adopt this for bot <em>dispatch acknowledgement</em>: between the user&#39;s command and the bot&#39;s reply, render a collapsed pill <code>bot:foo · dispatched · &lt;timestamp&gt;</code> that can expand to show the raw ACP/handshake trace if the user wants to debug. Default collapsed; one click reveals.</li><li><strong>Composer &quot;command mode&quot; affordance.</strong> When the composer detects a <code>@bot:</code> mention at the start of the message, switch the send button label from <code>Send</code> to <code>Dispatch</code> and tint the composer&#39;s left edge to match the bot-mention surface tint. Same input, different intent. Reference for the principle: Cursor&#39;s composer (same screen) shows <code>Add a follow up</code> with a small model-attribution chip below — the composer&#39;s footer reacts to the conversational state. We do the same with intent (chat vs. command) rather than with model selection.</li></ul><h3 id="avoid-1" tabindex="-1">Avoid <a class="header-anchor" href="#avoid-1" aria-label="Permalink to &quot;Avoid&quot;">​</a></h3><ul><li><strong>ChatGPT-style &quot;/&quot; slash commands rendered as chips in the composer.</strong> We&#39;ve already ruled this out in the prior pass — slash is for editor/system commands. Commands to a bot go through <code>@bot:&lt;alias&gt;</code>, not <code>/</code>. Keep the mental model clean: <code>/</code> is local, <code>@</code> is a network entity.</li><li>Rendering the bot&#39;s response with a giant header like Slackbot does (&quot;<code>/dispatch</code> from user X to bot Y completed at 14:32:01 UTC&quot;). We have the surrounding chat thread to anchor who sent what. The bot reply needs <strong>only</strong> an attribution pill + body.</li><li>Treating the bot&#39;s &quot;command failed&quot; state as a normal chat error toast. If the dispatch fails (handshake dropped mid-flight, capability rejected, runtime panic), render the failure <strong>inline in the same chat slot the response would have occupied</strong> — same monospace face, red surface tint, with a <code>Retry</code> chip and an <code>Open bot status</code> link to the settings row. No floating toast.</li></ul><h2 id="_3-bot-status-indicators-prd-§4-4" tabindex="-1">3. Bot status indicators (PRD §4.4) <a class="header-anchor" href="#_3-bot-status-indicators-prd-§4-4" aria-label="Permalink to &quot;3. Bot status indicators (PRD §4.4)&quot;">​</a></h2><p>§4.4 says the bots list shows handshake status — <code>pending</code> / <code>active</code> / <code>failed</code>. Errors must surface inline in the list, never as a toast. The strongest signal: developer-tool list rows with status pills and last-seen timestamps.</p><h3 id="borrow-2" tabindex="-1">Borrow <a class="header-anchor" href="#borrow-2" aria-label="Permalink to &quot;Borrow&quot;">​</a></h3><ul><li><strong>Fingerprint integration detail</strong> (<a href="https://refero.design/pages/d60dbde8-7ae3-4101-96dc-a33b4979675a" target="_blank" rel="noreferrer">screen d60dbde8</a>). Pattern: <code>Status</code> label on its own line under the title, followed by a single small pill (<code>Not Installed</code>). The pill is <em>boxy, neutral-bg, one word</em>, not a colored badge. We adopt the same boxy-pill aesthetic for our bot status: <ul><li><code>pending</code> — neutral pill (<code>base-200</code> bg), faint animated dot to the left to indicate in-flight.</li><li><code>active</code> — neutral pill, solid green dot to the left.</li><li><code>failed</code> — neutral pill, red dot, <strong>followed by the failure reason as inline text on the same row</strong>, e.g. <code>failed · signature rejected · 2m ago</code>.</li></ul></li><li><strong>Resend logs detail</strong> (<a href="https://refero.design/pages/cf561511-960a-4de5-8eb5-5772d669db1c" target="_blank" rel="noreferrer">screen cf561511</a>). Reference for the <em>bot detail</em> surface (clicked from the list). The Resend log shows a row of labelled metadata cells across the top: <code>ENDPOINT</code> / <code>DATE</code> / <code>STATUS</code> (with a green <code>200</code> pill) / <code>METHOD</code> / <code>USER-AGENT</code> / <code>ID</code>. Adopt the same metadata strip for our bot detail header: <code>Alias</code> / <code>Peer ID</code> (truncated + copy) / <code>Status</code> (pill) / <code>Last acked</code> / <code>Capability expires</code> / <code>Issued by</code>. Below the strip: the granted scopes, and an <code>Activity</code> block (the bot&#39;s recent ack/error events) styled the same way Resend renders request bodies — dark monospace card with copy-to-clipboard. This gives admins one place to debug a bot without diving into logs.</li><li><strong>Last seen / last acked timestamps.</strong> Borrow the relative + absolute pairing common in developer tools: <code>2m ago</code> rendered as the primary, full ISO timestamp on hover. Pulled from cross-product convention; no single Refero screen owns this.</li></ul><h3 id="avoid-2" tabindex="-1">Avoid <a class="header-anchor" href="#avoid-2" aria-label="Permalink to &quot;Avoid&quot;">​</a></h3><ul><li><strong>Cursor dashboard integrations</strong> (<a href="https://refero.design/pages/069970f5-0a6f-4ebf-964a-3cbf1744de7d" target="_blank" rel="noreferrer">screen 069970f5</a>). Cursor uses descriptive sub-text instead of a status pill (&quot;Connected as &#39;referodesignteam&#39; to repositories in GitHub organizations: referodesignteam&quot;). That works when there are 4 possible integrations and the connect/disconnect is binary; it does <em>not</em> work for our list, where bots can be in 3 states <em>and</em> surface a specific error message. Don&#39;t merge the state into the description. Keep the pill, keep the inline error.</li><li>Colored-background pills (green-bg <code>Active</code>, red-bg <code>Failed</code>). Too loud, fights the §3 density rules. Neutral bg + colored dot is enough.</li><li>Hiding errors behind a tooltip. The PRD explicitly forbids toast-only failures; we apply the same rule to tooltip-only failures.</li></ul><h2 id="_4-streaming-responses-assistant-bot" tabindex="-1">4. Streaming responses (assistant + bot) <a class="header-anchor" href="#_4-streaming-responses-assistant-bot" aria-label="Permalink to &quot;4. Streaming responses (assistant + bot)&quot;">​</a></h2><p>ACP backends stream tokens. The UI must show partial-message state, expose a stop-generation control, and offer regeneration after the stream finishes.</p><h3 id="borrow-3" tabindex="-1">Borrow <a class="header-anchor" href="#borrow-3" aria-label="Permalink to &quot;Borrow&quot;">​</a></h3><ul><li><strong>Manus — generating-video chat thread</strong> (<a href="https://refero.design/pages/413cdc41-3722-4b7a-b367-ebbbc5b88975" target="_blank" rel="noreferrer">screen 413cdc41</a>). Closest match to what we need. While the assistant is working, three things happen on screen at once: <ol><li>The in-progress message renders the partial body normally, with a <code>Generating video</code> inline status block (icon + &quot;It will take a few minutes, please wait...&quot; text + tiny spinner) sitting <em>within</em> the message.</li><li>A small <code>Thinking</code> chip with an animated dot appears beneath the message.</li><li>The composer&#39;s send button is replaced by a <strong>solid round black stop button</strong> with a white square glyph in the bottom-right corner of the composer. Same slot, swapped affordance. We adopt this verbatim: <ul><li>While streaming: composer&#39;s right-edge primary becomes the stop button.</li><li>On click: cancel the stream, the partial message stays, a faint <code>stopped · &lt;relative time&gt;</code> line appears under it with a <code>Regenerate ↻</code> chip.</li><li>After stream completes: stop button swaps back to send; a row of three chips appears beneath the assistant message: <code>↻ Regenerate</code> · <code>Copy</code> · <code>…</code> (overflow with &quot;Edit prompt&quot; / &quot;Branch from here&quot;).</li></ul></li></ol></li><li><strong>Raycast AI — Thinking state</strong> (<a href="https://refero.design/pages/d3118a5e-b48a-4a6b-b7d9-d0668641d05b" target="_blank" rel="noreferrer">screen d3118a5e</a>). When <em>no tokens have arrived yet</em> (initial latency before the first chunk), Raycast shows the dark <code>Thinking… &gt;</code> pill in place of the message body. Adopt for our zero-token state: if more than 500ms passes with no first token, render a <code>Thinking…</code> pill in the message slot; replace it with the actual streaming body the moment the first chunk arrives. Caret/blinking cursor at the end of the partial body indicates the stream is live.</li><li><strong>Stop = decisive, regenerate = optional.</strong> The stop control must be <em>visible at all times while streaming</em> — borrowed from Manus&#39;s persistent stop button — because cancelling is the user&#39;s escape valve for runaway responses. The regenerate chip is post-stream only; cluttering the in-flight UI with regenerate would tempt double-dispatch.</li></ul><h3 id="avoid-3" tabindex="-1">Avoid <a class="header-anchor" href="#avoid-3" aria-label="Permalink to &quot;Avoid&quot;">​</a></h3><ul><li><strong>ChatGPT&#39;s stop-button-where-the-send-button-was, <em>and</em> the streaming UI doubling the composer height.</strong> ChatGPT in some states pushes a &quot;Stop generating&quot; pill <em>above</em> the composer in addition to swapping the button. Two affordances for one action. Pick the swapped-button pattern only (Manus does this cleanly).</li><li>Showing the cursor as a typing animation that simulates per-character append when chunks actually arrive in larger batches. ACP delivers tokens, not characters; render whatever arrives, append it, blink a cursor at the tail. Don&#39;t fake typing.</li><li>Hiding the regenerate affordance in an overflow menu. It&#39;s the second-most-common action after &quot;copy&quot;. Surface it as a first-class chip.</li></ul><h2 id="_5-pattern-locks" tabindex="-1">5. Pattern locks <a class="header-anchor" href="#_5-pattern-locks" aria-label="Permalink to &quot;5. Pattern locks&quot;">​</a></h2><table tabindex="0"><thead><tr><th>PRD ref</th><th>Pattern locked from refs</th><th>Reference</th></tr></thead><tbody><tr><td>§4.3 add-backend form</td><td>Single-column form (Name · Transport URL · Auth radio with progressive disclosure · <code>Mark as default</code> checkbox · Cancel/Save). One screen, no wizard.</td><td>Linear 13f7be48</td></tr><tr><td>§4.3 backend list</td><td>Horizontal stripe rows: provider mark · name + one-line subtext · <code>Default</code> pill if applicable · right-aligned <code>Manage ⌄</code> (connected) or <code>Configure</code> (template).</td><td>Cursor 069970f5</td></tr><tr><td>§4.3 endpoint validation</td><td>Validate on blur; render inline under field — <code>Connected as &lt;agent name&gt;/&lt;version&gt;</code> or specific error. No toast, no separate &quot;Test&quot; button.</td><td>(cross-product convention; matches the §4.4 paste-on-blur lock)</td></tr><tr><td>§4.3 default flag</td><td>Pill <code>Default</code> to the right of the backend name; set/unset from row menu; allow zero defaults.</td><td>(composite — not a single Refero screen)</td></tr><tr><td>§4.6 command body rendering</td><td>User message: text up to the <code>@bot:</code> pill in proportional face, body after it wrapped in monospace + <code>$</code> prefix. Bot reply: bot-attribution pill in header; monospace for structured output, proportional for prose.</td><td>Cursor 5f4c68ff</td></tr><tr><td>§4.6 dispatch ack</td><td>Collapsed pill between command and reply: <code>bot:foo · dispatched · &lt;timestamp&gt;</code>; expandable to show ACP/handshake trace.</td><td>Raycast d3118a5e</td></tr><tr><td>§4.6 composer intent shift</td><td>When composer text begins with <code>@bot:</code>, send button label → <code>Dispatch</code>; left edge tinted to bot-mention surface.</td><td>Cursor 5f4c68ff (composer footer reacts to state)</td></tr><tr><td>§4.6 failure rendering</td><td>Inline in the same chat slot the response would occupy: monospace face, red surface tint, <code>Retry</code> chip, <code>Open bot status</code> link. No toast.</td><td>(PRD §4.4 rule extended)</td></tr><tr><td>§4.4 status pill</td><td>Neutral-bg boxy pill + colored dot (<code>pending</code> faint animated, <code>active</code> solid green, <code>failed</code> red); inline failure reason on the same row.</td><td>Fingerprint d60dbde8</td></tr><tr><td>§4.4 bot detail header</td><td>Labelled metadata strip — <code>Alias</code> / <code>Peer ID</code> (copy) / <code>Status</code> / <code>Last acked</code> / <code>Capability expires</code> / <code>Issued by</code> — over an Activity block in monospace card style.</td><td>Resend cf561511</td></tr><tr><td>Streaming in-flight</td><td>Partial body renders live; <code>Thinking…</code> pill for sub-first-token latency; composer right-edge primary swaps to a solid round stop button.</td><td>Manus 413cdc41 + Raycast d3118a5e</td></tr><tr><td>Streaming post-flight</td><td>Below the completed assistant message: <code>↻ Regenerate</code> · <code>Copy</code> · <code>…</code> chip row. Regenerate is first-class, not overflow.</td><td>Manus 413cdc41</td></tr></tbody></table><h2 id="_6-open-follow-up" tabindex="-1">6. Open follow-up <a class="header-anchor" href="#_6-open-follow-up" aria-label="Permalink to &quot;6. Open follow-up&quot;">​</a></h2><ul><li><strong>Multi-backend per-message override UI.</strong> §4.5 (locked in the prior pass) puts the backend switcher in the composer footer. With multiple configured backends + a default flag, the dropdown needs to show <code>Default</code> next to the marked entry, the others below, and an <code>Add backend…</code> footer item. None of the reviewed screens model exactly this (multi-backend <em>with</em> a default-flag concept) — confirm via a Storybook spike when we build <code>BackendSwitcher</code>.</li><li><strong>Bot capability expiry warnings.</strong> PRD §4.4 step 2 includes an expiry. We need a pattern for <em>&quot;about to expire&quot;</em> in the bots list (e.g. 7 days out): probably a yellow dot variant of the status indicator + &quot;expires in 6d&quot; inline text. Not covered above; settle when building <code>BotCatalogList</code>.</li><li><strong>Token-cost / usage readout during streaming.</strong> Some refs (Cursor agent detail, Parallel AI playground) show a tokens-used counter alongside the streaming message. Soma&#39;s v0 stays silent on cost — but the slot in the UI (post-message footer line, faint text) should be reserved so we don&#39;t have to refactor to add it.</li><li><strong>Bot transcript export.</strong> Resend&#39;s monospace metadata card is the right surface for showing a per-bot event log; we should think about a &quot;Copy as JSON&quot; button on each event row from day one, since bot debugging is a developer task.</li></ul><hr><p><em>Next pass after this lands: fold the §4.3 add-backend form pattern + the §4.6 command rendering rules into the PRD body; promote the status-pill + Activity-strip rows above into ADR-0005 alongside the prior refs.</em></p>',35)])])}const m=t(s,[["render",n]]);export{u as __pageData,m as default};
